-- Datos para tabla: activities (77 registros)
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (25, 1, 1, 5, 'lunes', 1, 'El Salto Ángel y el Secreto de los Tepuyes', 'Descubre la magia del Churún Merú y la sabiduría ancestral del pueblo Pemón.', 'En el corazón del estado Bolívar se alza el Auyantepuy, una colosal montaña de roca plana que los indígenas Pemones consideran sagrada. Desde su cumbre desciende el Salto Ángel (conocido en lengua indígena como Kerepakupai Vená o Churún Merú), la caída de agua ininterrumpida más alta del planeta Tierra, con casi un kilómetro de altura libre (979 metros).

Para los antiguos pemones, estas majestuosas mesetas no son montañas comunes: son guardianes del tiempo que tocan el cielo. Cuentan que cuando el agua cae y se transforma en una neblina dorada al chocar con el viento, la selva canta agradeciendo la vida que nutre a los ríos Churún y Caroní.

Comprender este texto nos enseña que Venezuela posee maravillas geográficas únicas en el mundo y que nuestros pueblos originarios tenían una relación de profundo respeto y cuidado hacia la naturaleza.', 'Identifica la idea principal del texto y explica por qué los pemones consideraban sagrado al Auyantepuy.', 50, 1, 1, '2026-10-06 10:00:52');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (26, 1, 1, 5, 'lunes', 2, 'Los Decimales en las Compras Cotidianas', 'Aprende a sumar y restar números decimales resolviendo compras prácticas.', 'Los números decimales están presentes todos los días: cuando medimos nuestra estatura (1,45 m), cuando compramos frutas en kilogramos (2,5 kg) o al pagar productos.

Un número decimal tiene dos partes separadas por una coma:
• La parte entera (a la izquierda de la coma): 12 unidades.
• La parte decimal (a la derecha de la coma): décimas, centésimas y milésimas (ej: 0,75).

REGLA DE ORO PARA SUMAR Y RESTAR DECIMALES:
Para sumar o restar, coloca siempre la coma debajo de la coma, alineando unidades con unidades, décimas con décimas y centésimas con centésimas.

Ejemplo:
  1 5 , 4 0  (Kilo de queso)
+  8 , 2 5  (Litro de leche)
──────────
  2 3 , 6 5  en total.', 'Si compras un cuaderno por 4,50 y un lápiz por 1,75, ¿cuánto gastas en total? ¿Cuánto te sobra si pagas con un billete de 10?', 50, 2, 1, '2026-10-06 10:00:52');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (27, 1, 1, 5, 'lunes', 6, 'Nuestra Guaira: Entre el Mar y la Montaña', 'Comprende la geografía especial de nuestro estado y por qué debemos estar preparados.', 'El estado La Guaira tiene una de las geografías más hermosas y singulares del mundo. Es una franja de tierra angosta ubicada justo entre dos gigantes:
1. Al norte: El inmenso Mar Caribe.
2. Al sur: La imponente cordillera de la Costa (nuestro Parque Nacional Waraira Repano), con montañas muy empinadas de más de 2.000 metros de altura.

¿Por qué es importante conocer esto?
Porque en La Guaira convivimos con dos fuerzas de la naturaleza:
• Los ríos y quebradas que nacen en la cumbre de la montaña y descienden con gran velocidad hacia el mar.
• El contacto entre la tierra y el mar.

Estar preparados no significa tener miedo: ¡significa ser inteligentes y conocer nuestro hogar! Cuando conocemos cómo funciona la montaña, los ríos y el mar, aprendemos a cuidar nuestras casas, no botar basura en los cauces y saber cómo actuar en equipo con la familia.', 'Dibuja en tu mente o en un papel cómo se ubica La Guaira entre el Ávila y el mar. Menciona dos ríos o quebradas que conozcas.', 60, 3, 1, '2026-10-06 10:00:52');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (28, 1, 1, 5, 'martes', 3, 'El Misterio de las Balanzas en Equilibrio', 'Iniciación al álgebra visual descubriendo pesos y valores ocultos.', 'El álgebra es como un juego de detectives donde descubrimos números secretos.

Imagina una balanza antigua de dos platos que está perfectamente equilibrada (ambos lados pesan exactamente lo mismo).

En el plato izquierdo hay: 1 Piña + 2 Kilos de pesas.
En el plato derecho hay: 7 Kilos de pesas.

Como la balanza está en equilibrio, sabemos que:
Piña + 2 kg = 7 kg

¿Cuánto pesa la piña?
Si quitamos 2 kg de ambos lados para no perder el equilibrio:
Piña = 7 - 2 = 5 kg.

¡Felicidades! Acabas de resolver tu primera ecuación de manera intuitiva. En matemáticas, a esa ''piña'' desconocida la solemos llamar con una letra, como la letra X.', 'Si una caja misteriosa + 6 monedas = 15 monedas, ¿cuántas monedas hay dentro de la caja misteriosa?', 50, 1, 1, '2026-10-06 10:00:52');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (29, 1, 1, 5, 'martes', 4, 'Los Primeros Pobladores y la Costa Venezolana', 'Conoce cómo vivían los pueblos originarios indígenas en las costas e islas.', 'Mucho antes de la llegada de los barcos españoles, las tierras venezolanas estaban habitadas por diversas comunidades indígenas con culturas asombrosas.

En la región costera central y oriental vivían principalmente los pueblos Caribes y Arawacos:
• Eran navegantes expertos que construían canoas resistentes para pescar en el mar y comerciar entre islas.
• Se alimentaban de pescado fresco, mariscos, yuca con la que preparaban el casabe (un pan crujiente y duradero que hoy seguimos comiendo), maíz y frutas silvestres.
• Vivían en chozas construidas con palmas y madera adaptadas al clima tropical fresco.

El casabe que hoy compramos en el mercado tiene más de mil años de tradición gracias a nuestros antepasados indígenas.', 'Nombra tres alimentos que consumían los pueblos indígenas en la costa venezolana.', 50, 2, 1, '2026-10-06 10:00:52');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (30, 1, 1, 5, 'martes', 5, 'Los Tres Estados de la Materia en Casa', 'Sólido, líquido y gaseoso explicados a través de experiencias en la cocina.', 'Todo lo que nos rodea en el universo está hecho de MATERIA: el aire que respiras, el agua que bebes y la pantalla de tu celular.

La materia se presenta comúnmente en tres estados fundamentales:

1. SÓLIDO: Tiene forma fija y volumen definido. Las partículas están muy juntas y ordenadas. Ejemplo: Un cubito de hielo, una roca, un lápiz.
2. LÍQUIDO: Tiene volumen definido pero adopta la forma del recipiente que lo contiene. Las partículas se mueven con libertad. Ejemplo: El agua en un vaso, la leche, el aceite.
3. GASEOSO: No tiene forma ni volumen fijos; se expande ocupando todo el espacio disponible. Las partículas están muy separadas. Ejemplo: El vapor de agua que sale de la olla al hervir, el aire dentro de un globo.', 'Observa un cubito de hielo derritiéndose. ¿De qué estado a qué estado cambió la materia?', 50, 3, 1, '2026-10-06 10:00:52');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (31, 1, 1, 5, 'miercoles', 2, 'Multiplicar Decimales por 10, 100 y 1.000 (El Truco de la Coma)', 'Aprende el método ultra-rápido de correr la coma a la derecha sin hacer cuentas largas.', '¿Sabías que existe un truco mágico para multiplicar cualquier número decimal por 10, 100 o 1.000 en un segundo?

¡No necesitas hacer una multiplicación larga en papel! Solo debes CORRER LA COMA hacia la DERECHA tantos lugares como ceros tenga el número:

• Multiplicar por 10 (tiene 1 cero): Ruedas la coma 1 lugar a la derecha.
  Ejemplo: 3,45 × 10 = 34,5

• Multiplicar por 100 (tiene 2 ceros): Ruedas la coma 2 lugares a la derecha.
  Ejemplo: 3,45 × 100 = 345

• Multiplicar por 1.000 (tiene 3 ceros): Ruedas la coma 3 lugares a la derecha (si faltan números, agregas ceros).
  Ejemplo: 3,45 × 1.000 = 3.450', 'Aplica el truco con 8,72 × 10 y con 0,5 × 100.', 50, 1, 1, '2026-10-06 10:00:52');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (32, 1, 1, 5, 'miercoles', 6, 'Crecidas de Ríos y Quebradas: Alertas en la Montaña', 'Aprende a reconocer las señales naturales antes de que una quebrada o río crezca.', 'En La Guaira, las cuencas de los ríos nacen muy alto en el Parque Nacional Waraira Repano y bajan por pendientes pronunciadas.

A veces, en la costa (donde están nuestras casas) puede estar lloviendo suavemente o incluso hacer sol, pero en la cumbre de la montaña puede estar cayendo un aguacero torrencial prolongado.

¿Cuáles son las SEÑALES DE ALERTA TEMPRANA de una crecida?
1. CAMBIO DE COLOR DEL AGUA: Si el agua del río o quebrada se vuelve repentinamente marrón oscura o chocolatosa con mucho barro, significa que la montaña está drenando sedimentos.
2. RUIDO SORDO O RETUMBO: Un sonido grave similar a un camión pesado que viene desde la parte alta de la montaña (provocado por piedras que chocan bajo el agua).
3. TRONCOS O RAMAS FLOTANDO: Aparición repentina de vegetación arrastrada por la corriente.

¿QUÉ HACER DE INMEDIATO?
• Nunca cruzar un río o quebrada crecida a pie ni en vehículo.
• Alejarse de las orillas del cauce y dirigirse a zonas altas y seguras de inmediato.
• Avisar a los adultos sin perder tiempo intentando rescatar objetos materiales.', 'Pregunta a tus padres qué quebrada o cauce queda más cerca de su hogar y cuál es la calle o zona más alta y segura para resguardarse.', 60, 2, 1, '2026-10-06 10:00:52');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (33, 1, 1, 5, 'jueves', 3, 'Descubriendo el Número Perdido (Ecuaciones Aditivas)', 'Aprende a despejar incógnitas usando la operación contraria.', 'Ayer descubrimos que una incógnita es un número escondido detrás de una letra o símbolo.

Hoy aprenderemos la regla de los matemáticos para despejar ese número secreto:
¡LA OPERACIÓN INVERSA!

Si un número está SUMANDO al lado de la incógnita, pasa al otro lado de la igualdad RESTANDO.

Ejemplo:
  X + 15 = 40

¿Cómo dejamos a la X completamente sola?
El 15 que está sumando se va al otro lado a restar:
  X = 40 - 15
  X = 25

¡Comprobémoslo!
25 + 15 = 40. ¡Funciona perfecto!', 'Resuelve: X + 23 = 50. ¿Cuánto vale X?', 50, 1, 1, '2026-10-06 10:00:52');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (34, 1, 1, 5, 'jueves', 4, 'Gual y España: Los Héroes Patriotas de La Guaira (1797)', 'El primer gran movimiento revolucionario por la igualdad y la libertad nació en nuestro puerto.', '¿Sabías que La Guaira fue el escenario del primer gran grito revolucionario por la independencia de Venezuela?

En 1797, dos valientes hombres de nuestra tierra:
• Manuel Gual (militar de La Guaira) y
• José María España (lugarteniente de Macuto)

junto a otros vecinos, organizaron una conspiración histórica contra el dominio colonial español.

Su proyecto fue sumamente avanzado para su época porque proclamaba:
1. La abolición total de la esclavitud.
2. La igualdad absoluta entre blancos, pardos, indígenas y negros.
3. La libertad de comercio y el fin de los impuestos opresivos.
4. Diseñaron además una hermosa bandera de cuatro colores (blanco, azul, amarillo y rojo) con 4 estrellas que representaban las provincias.

Aunque el movimiento fue descubierto y enfrentó duras represalias, sembró para siempre la semilla de la patria soberana en el corazón de los guaireños.', 'Investiga qué monumento o plaza en La Guaira recuerda a José María España.', 50, 2, 1, '2026-10-06 10:00:52');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (35, 1, 1, 5, 'viernes', 6, 'Misión Familiar: La Mochila de las 72 Horas', 'Aprende qué objetos son vitales en una emergencia y cuáles no debemos cargar.', 'En cualquier hogar de La Guaira, ante lluvias intensas, movimientos sísmicos o emergencias, una familia preparada debe tener lista su ''Mochila de las 72 Horas''.

¿Por qué 72 horas? Porque son las primeras 3 jornadas en las que los servicios de agua, luz o rescate pueden tardar en restablecerse mientras las autoridades atienden la zona.

ELEMENTOS VITALES QUE SÍ DEBEN IR:
1. Agua potable embotellada (mínimo 2 litros por persona).
2. Linterna resistente y pilas de repuesto.
3. Radio portátil a baterías (para escuchar comunicados oficiales sin depender de internet).
4. Botiquín de primeros auxilios (alcohol, gasas, curitas, medicamentos familiares).
5. Alimentos no perecederos enlatados (atún, sardinas, galletas) que abran sin abrelatas.
6. Copias de documentos importantes (cédulas, títulos) dentro de una bolsa plástica hermética zíploc.
7. Silbato o pito (hace mucho más ruido que gritar si se necesita auxilio).

LO QUE NO DEBE IR:
• Objetos pesados, juguetes grandes o televisores que quiten agilidad o causen tropiezos.', 'Revisa con tus padres qué elementos de esta lista ya tienen en casa y en qué lugar seguro guardarán la mochila.', 70, 1, 1, '2026-10-06 10:00:52');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (36, 1, 1, 5, 'viernes', 2, 'El Gran Reto Matemático del Fin de Semana', 'Pon a prueba todo lo aprendido en la semana y gana el trofeo de puntos.', '¡Llegamos al final de la semana, Dimas!

Has demostrado mucha perseverancia estudiando desde casa. En este desafío final pondrás a prueba:
• Sumas y restas con decimales.
• Multiplicación rápida por potencias de 10.
• Descubrir números incógnitas.

Lee cada pregunta con calma, ten a mano un lápiz y una hoja de papel borrador para hacer tus anotaciones, ¡y a triunfar!', 'Haz los cálculos en tu cuaderno borrador antes de marcar tu respuesta final.', 60, 2, 1, '2026-10-06 10:00:52');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (49, 1, 1, 5, 'miercoles', 13, 'La Fotosíntesis: La Gran Fábrica Verde de Oxígeno', 'Descubre cómo las plantas transforman la luz del sol, el agua y el aire en vida y oxígeno puro.', 'Las plantas son seres vivos extraordinarios y los grandes pulmones de nuestro planeta Tierra.

A diferencia de los animales y los seres humanos, que tenemos que buscar comida, las plantas tienen una capacidad asombrosa: fabrican su propio alimento mediante un proceso biológico llamado FOTOSÍNTESIS.

¿CÓMO FUNCIONA ESTA FÁBRICA VERDE?
1. Raíces: Absorben agua y minerales del suelo.
2. Hojas: Tienen un pigmento verde llamado CLOROFILA, que funciona como un pequeño panel solar que atrapa la luz del Sol.
3. Aire: A través de poros diminutos en las hojas (estomas), la planta absorbe Dióxido de Carbono (CO2).

Con luz solar, agua y CO2, la planta elabora GLUCOSA (su energía) y libera al aire OXÍGENO puro (O2), que es el gas que todos los seres humanos necesitamos para respirar.

¡Por eso cuidar los árboles en nuestras comunidades y en el Parque Nacional Waraira Repano es vital para respirar aire limpio todos los días!', 'Observa una planta de tu casa o cerca de tu ventana. Toca suavemente una de sus hojas e identifica cómo le llega la luz del sol.', 50, 3, 1, '2026-10-06 13:19:10');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (50, 1, 1, 5, 'jueves', 14, 'El Poder de la Empatía y el Respeto en Familia', 'Aprende qué es ser un buen ciudadano empezando desde el hogar, la escuela y la comunidad.', 'Ser ciudadano no es solo tener un documento de identidad o vivir en una ciudad. Ser un buen ciudadano es una actitud diaria de respeto, colaboración y empatía con las personas que nos rodean.

¿QUÉ ES LA EMPATÍA?
La empatía es la capacidad de ponernos en los zapatos de la otra persona, intentando comprender lo que siente y lo que necesita antes de juzgar o molestarnos. Por ejemplo:
• Si tu hermano o un compañero está triste o cansado, preguntarle con cariño cómo se siente en lugar de burlarse.
• Si papá o mamá están ocupados trabajando, colaborar recogiendo nuestro plato o manteniendo el cuarto ordenado.

REGLAS DE ORO DE LA BUENA CONVIVENCIA:
1. Escuchar activamente cuando los demás nos hablan.
2. Usar palabras mágicas: ''Por favor'', ''Gracias'', ''Disculpa'' y ''Buenos días''.
3. Resolver los desacuerdos conversando con calma, sin gritar ni agredir.

Cuando practicamos estos valores en casa, nos convertimos en ciudadanos valiosos que construyen una sociedad pacífica y solidaria.', 'El Reto de la Amabilidad: Realiza hoy una acción servicial en casa sin que nadie te la pida (por ejemplo, acomodar tus libros o ayudar a limpiar).', 50, 3, 1, '2026-10-06 13:19:10');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (51, 1, 1, 5, 'viernes', 13, 'Fauna Venezolana y Cadenas Alimenticias', 'Conoce cómo los animales y plantas interactúan en los ecosistemas de Venezuela.', 'Venezuela es uno de los países con mayor variedad de animales en todo el mundo. En nuestra tierra conviven aves de colores brillantes, mamíferos únicos y peces asombrosos.

¿QUÉ ES UNA CADENA ALIMENTICIA?
En la naturaleza, todos los seres vivos están conectados a través de la alimentación:

1. Productores: Las plantas y algas, que fabrican su propio alimento con la luz del sol.
2. Consumidores Primarios (Herbívoros): Animales que comen plantas. Por ejemplo, el Chigüire (el roedor más grande del mundo) comiendo hierbas en los llanos.
3. Consumidores Secundarios (Carnívoros): Depredadores que cazan otros animales para alimentarse, como el imponente Jaguar o el Águila Harpía.
4. Descomponedores: Hongos y bacterias del suelo que transforman los restos orgánicos en nutrientes para que nuevas plantas crezcan.

Si cuidamos a cada especie y protegemos sus hábitats naturales, mantenemos el equilibrio ecológico que permite la vida de todos.', 'Nombra tres animales que vivan en Venezuela y clasifícalos según lo que comen (herbívoro, carnívoro u omnívoro).', 50, 3, 1, '2026-10-06 13:19:10');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (64, 1, 1, 5, 'lunes', 1, 'El Viaje de la Semilla: Idea Principal y Secuencia Narrativa', 'Aprende a identificar la idea principal en un cuento y distinguir el inicio, nudo y desenlace.', 'Los textos narrativos cuentan historias reales o imaginarias que ocurren en un lugar y tiempo determinados. Toda narración bien construida tiene tres partes fundamentales:

1. **Inicio:** Se presentan los personajes, el lugar y la situación inicial.
2. **Nudo o conflicto:** Ocurre un problema o acontecimiento que cambia la tranquilidad de los personajes.
3. **Desenlace:** Se resuelve el conflicto y concluye la historia.

Para hallar la **idea principal**, pregúntate siempre: *¿De qué o de quién trata principalmente el texto y qué es lo más importante que se dice sobre ello?*', 'Escribe en tu cuaderno un cuento corto de 6 líneas sobre una mascota que encuentra un mapa secreto. Señala con colores distintos el inicio, el nudo y el desenlace.', 50, 1, 1, '2026-10-06 19:41:42');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (65, 1, 1, 5, 'martes', 2, 'El Sistema de Numeración Decimal: Unidades, Decenas y Millones', 'Descubre cómo cada dígito cambia de valor según su posición en la tabla de valor posicional.', 'Nuestro sistema de numeración es **posicional y de base 10**. Esto significa que diez unidades de un orden forman una unidad del orden inmediatamente superior:

- 10 Unidades (U) = 1 Decena (D)
- 10 Decenas (D) = 1 Centena (C)
- 10 Centenas (C) = 1 Unidad de Mil (UM)
- 1.000 Unidades de Mil = 1 Unidad de Millón (UMi)

Por ejemplo, en el número **4.528.319**:
El dígito 4 está en las unidades de millón y vale 4.000.000.
El dígito 5 está en las centenas de mil y vale 500.000.', 'Descompón aditivamente el número 3.842.105 según el valor posicional de cada una de sus cifras en tu cuaderno.', 50, 1, 1, '2026-10-06 19:41:42');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (66, 1, 1, 5, 'miercoles', 13, 'La Célula: El Ladrillo Fundamental de los Seres Vivos', 'Explora cómo están formados todos los organismos vivos y la diferencia entre células animales y vegetales.', 'Todos los seres vivos en la Tierra, desde las bacterias microscópicas hasta los jaguares y samanes, están formados por **células**. Las tres partes esenciales de toda célula eucariota son:

1. **Membrana plasmática:** Envoltura que protege a la célula y controla qué sustancias entran y salen.
2. **Citoplasma:** Líquido gelatinoso donde flotan los organelos encargados de las funciones celulares.
3. **Núcleo:** El centro de mando que contiene el ADN (material genético).

*Diferencia clave:* Las células vegetales tienen **pared celular rígida** y **cloroplastos** (para hacer fotosíntesis con la luz solar), organelos que no tienen las células animales.', 'Dibuja en tu cuaderno una célula vegetal y rotula sus tres partes principales más la pared celular.', 50, 1, 1, '2026-10-06 19:41:42');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (67, 1, 1, 5, 'jueves', 6, 'Nuestra Geografía: La Cordillera de la Costa y La Guaira', 'Conoce cómo las montañas se unen con el mar Caribe en La Guaira y por qué debemos cuidar las cuencas.', 'El estado La Guaira posee una geografía muy especial: es una estrecha franja costera flanqueada por la imponente **Cordillera de la Costa** (Parque Nacional Waraira Repano) y el mar Caribe.

Debido a que las montañas tienen pendientes muy pronunciadas, las quebradas y ríos bajan rápidamente hacia el mar. Cuando caen lluvias torrenciales continuas, el agua arrastra sedimentos y rocas.

Por esta razón, la **gestión de riesgos** es una prioridad para todos los guaireños:
- Mantener limpias las quebradas sin arrojar basura.
- Reforestar las laderas montañosas para que las raíces afiancen la tierra.
- Conocer las rutas de evacuación hacia zonas altas y seguras.', 'Conversa con tu familia e identifiquen juntos cuál es la zona alta más segura cercana a su vivienda en caso de lluvias fuertes.', 50, 1, 1, '2026-10-06 19:41:42');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (68, 1, 1, 5, 'viernes', 14, 'El Arte de Convivir: Acuerdos de Paz y Respeto Mutuo', 'Descubre por qué las normas no son castigos sino acuerdos que protegen nuestros derechos.', 'La convivencia es la capacidad de vivir juntos en armonía, respetando las ideas, gustos y diferencias de los demás. En la casa y en la escuela, los **acuerdos de convivencia** son indispensables:

- **Escucha activa:** Escuchar cuando otra persona habla sin interrumpirla.
- **Palabras mágicas:** Por favor, gracias, con permiso y disculpa.
- **Empatía:** Ponerse en los zapatos del compañero antes de emitir un juicio.
- **Solución pacífica:** Dialogar con calma cuando surge un desacuerdo en lugar de pelear o gritar.

Cuando practicamos estos valores, nuestro hogar y nuestra aula se convierten en un refugio de aprendizaje y amistad.', 'Escribe en tu cuaderno tres acuerdos de convivencia que te comprometes a cumplir esta semana en tu hogar con tus padres y hermanos.', 50, 1, 1, '2026-10-06 19:41:42');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (37, 1, 1, 6, 'lunes', 2, 'Mínimo Común Múltiplo (m.c.m.) y Fracciones con Distinto Denominador', 'Aprende a sumar y restar fracciones heterogéneas encontrando el denominador común.', 'En 6to grado las fracciones se vuelven una herramienta poderosa. Cuando sumamos fracciones con el mismo denominador (como 1/4 + 2/4 = 3/4) es muy sencillo.

Pero, ¿qué ocurre cuando tienen distinto denominador? (Por ejemplo: 1/3 + 2/5).
¡No podemos sumar directamente los de abajo! Necesitamos encontrar el Mínimo Común Múltiplo (m.c.m.).

PASOS PARA SUMAR FRACCIONES HETEROGÉNEAS:
1. Descomponer los denominadores en factores primos o buscar el menor múltiplo común.
   Para 3 y 5: Múltiplos de 3 (3, 6, 9, 12, 15...). Múltiplos de 5 (5, 10, 15...).
   El m.c.m. es 15.

2. Convertir cada fracción a denominador 15:
   • (15 ÷ 3) × 1 = 5  -> 5/15
   • (15 ÷ 5) × 2 = 6  -> 6/15

3. Ahora sí sumamos los numeradores:
   5/15 + 6/15 = 11/15.

¡Listo! Esa es la técnica maestra de los matemáticos.', 'Calcula en papel la suma de 1/2 + 1/4 usando el m.c.m.', 50, 1, 1, '2026-10-06 10:00:52');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (38, 1, 1, 6, 'lunes', 6, 'La Falla de San Sebastián y la Tectónica en La Guaira', 'Comprende científicamente por qué tiembla en nuestro litoral y derriba mitos sobre sismos.', 'Alexander, el reciente doblete sísmico que sentimos en casa no ocurrió por casualidad: tiene una explicación científica fascinante que todo estudiante de 6to grado debe dominar.

La corteza terrestre no es una sola cáscara sólida, sino un rompecabezas de gigantescos bloques en constante movimiento llamados PLACAS TECTÓNICAS.

Venezuela se encuentra justo en el límite de choque y roce entre dos placas colosales:
1. La Placa del Caribe (al norte, bajo el mar).
2. La Placa Suramericana (al sur, donde está nuestro continente).

En la franja del estado La Guaira existe una de las fallas geológicas activas más importantes del país: LA FALLA DE SAN SEBASTIÁN, que corre sumergida paralelamente a nuestra costa.

Cuando estas placas rozan y liberan energía acumulada, la corteza vibra: ese es el temblor o sismo.

PROTOCOLO CIENTÍFICO ANTE UN SISMO:
• NUNCA CORRER desesperadamente por escaleras durante la vibración fuerte (es la principal causa de fracturas).
• APLICAR: ''Agáchate, cúbrete y agárrate'' bajo una mesa resistente o junto a un pilar estructural.
• ALEJARSE de ventanas de vidrio, cables eléctricos y objetos colgantes.
• Una vez que cese el movimiento, evacuar calmadamente hacia espacios abiertos despejados.', 'Identifica en tu casa los 2 lugares más seguros (lejos de vidrios y estantes pesados) para resguardarte en caso de un sismo.', 60, 2, 1, '2026-10-06 10:00:52');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (39, 1, 1, 6, 'lunes', 1, 'El Primer Cable Submarino y la Conexión de La Guaira con el Mundo', 'Lectura histórica sobre cómo el litoral central fue la puerta de entrada de las comunicaciones globales.', 'A finales del siglo XIX, las cartas enviadas en barcos de vapor tardaban semanas e incluso meses en cruzar el océano Atlántico desde Europa o América del Norte hasta Venezuela.

Todo cambió radicalmente en 1888, cuando el puerto de La Guaira se convirtió en el punto de anclaje del primer cable telegráfico submarino intercontinental de Venezuela. Un gigantesco cordón de cobre aislado con caucho natural fue depositado en el fondo del lecho marino caribeño, conectando La Guaira con las Antillas y con las redes mundiales.

Por primera vez en la historia de la nación, una noticia sucedida en París, Londres o Nueva York podía ser recibida en La Guaira en cuestión de minutos gracias al código Morse y a los impulsos eléctricos.

Este hito transformó a La Guaira no solo en el puerto marítimo principal del país, sino en la capital de las telecomunicaciones internacionales, demostrando el papel estratégico que nuestro litoral ha jugado en todas las épocas.', 'Subraya las palabras desconocidas y resume en tres oraciones la importancia del cable submarino.', 50, 3, 1, '2026-10-06 10:00:52');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (40, 1, 1, 6, 'martes', 3, 'Del Español al Álgebra: Traduciendo Palabras a Números y Letras', 'Aprende a formular expresiones algebraicas a partir de enunciados de la vida real.', 'El lenguaje algebraico es como traducir un idioma: convertimos oraciones comunes en fórmulas matemáticas concisas.

GUÍA DE TRADUCCIÓN BÁSICA:
• ''Un número cualquiera'': Lo representamos con una letra, como $x o $y.
• ''El doble de un número'': 2x
• ''El triple de un número'': 3x
• ''La mitad de un número'': $x / 2 o x/2
• ''Un número aumentado en 7'': $x + 7
• ''Un número disminuido en 4'': $x - 4
• ''El doble de un número más 5'': 2x + 5

Ejemplo práctico:
Si decimos: ''La edad de Alex aumentada en 3 años es igual a 14''.
Traducción: $x + 3 = 14.
¿Cuántos años tiene Alex? Despejamos: $x = 14 - 3 = 11 años. ¡Exacto!', 'Traduce a lenguaje algebraico: "El triple de un número disminuido en 8".', 50, 1, 1, '2026-10-06 10:00:52');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (41, 1, 1, 6, 'martes', 4, 'El 19 de Abril de 1810: El Nacimiento de la Soberanía', 'Análisis del Cabildo de Caracas y la decisión popular que inició la emancipación.', 'El 19 de abril de 1810 marcó un punto de inflexión definitivo en la historia de Venezuela.

Aprovechando que España había sido invadida por las tropas francesas de Napoleón Bonaparte y el rey Fernando VII estaba cautivo, los criollos caraqueños se reunieron en la Plaza Mayor de Caracas (frente a la Catedral) para discutir el destino político de la Capitanía General.

El Capitán General español, Vicente Emparan, intentó mantener su autoridad absolutista. Sin embargo, el canónigo José Cortés de Madariaga se colocó detrás de Emparan en el balcón del Ayuntamiento e hizo señas al pueblo congregado abajo en la plaza para que dijeran ''¡NO!''.

Al preguntar Emparan: ''¿Deseáis que siga gobernando?'', la multitud gritó unánimemente: ''¡No lo queremos!''. Con dignidad, Emparan respondió: ''Pues yo tampoco quiero mando'', renunciando a su cargo.

Ese día se formó la Suprema Junta Conservadora de los Derechos de Fernando VII, el primer gobierno autónomo electo en Venezuela, que allanó el camino para la firma del Acta de Independencia el 5 de julio de 1811.', 'Explica con tus palabras la diferencia entre el 19 de abril de 1810 y el 5 de julio de 1811.', 50, 2, 1, '2026-10-06 10:00:52');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (42, 1, 1, 6, 'martes', 5, 'La Célula: Fábrica Microscópica de la Vida', 'Explora los organelos celulares y comprende las diferencias entre células animales y vegetales.', 'Todos los seres vivos —desde las bacterias más diminutas hasta las gigantescas ballenas y los árboles del Waraira Repano— están formados por CÉLULAS. La célula es la unidad anatómica, funcional y de origen de toda la vida.

PARTES BÁSICAS DE UNA CÉLULA EUCARIOTA:
1. Membrana Plasmática: La pared protectora que regula qué sustancias entran y salen.
2. Citoplasma: Líquido gelatinoso donde flotan los organelos.
3. Núcleo: El centro de mando donde se almacena el ADN (instrucciones genéticas).
4. Mitocondrias: Las plantas generadoras de energía que respiran y producen combustible para la célula.

¿QUÉ TIENEN LAS CÉLULAS VEGETALES QUE NO TIENEN LAS ANIMALES?
• Pared celular rígida (de celulosa) que les da firmeza.
• Cloroplastos con clorofila, encargados de realizar la fotosíntesis para fabricar su propio alimento usando la luz solar.', 'Menciona los dos organelos presentes exclusivamente en las células vegetales.', 50, 3, 1, '2026-10-06 10:00:52');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (43, 1, 1, 6, 'miercoles', 2, 'Porcentajes y Descuentos en la Vida Real', 'Aprende a calcular el 10%, 25% y 50% mentalmente para aplicar en compras y finanzas.', 'El porcentaje (%) representa una fracción de 100 partes. Cuando vemos ''20%'', significa literalmente ''20 de cada 100''.

TRUCOS DE CÁLCULO MENTAL RÁPIDO:
• 50%: Es exactamente la MITAD del número (dividir entre 2).
  Ejemplo: El 50% de 80 es 40.
• 25%: Es la CUARTA PARTE del número (la mitad de la mitad, dividir entre 4).
  Ejemplo: El 25% de 80 es 20.
• 10%: Es dividir el número entre 10 (correr la coma un lugar a la izquierda).
  Ejemplo: El 10% de 120 es 12.
• 20%: Calculas el 10% y lo multiplicas por 2.
  Ejemplo: Si el 10% de 120 es 12, el 20% es 24.

CÁLCULO CON FÓRMULA GENERAL:
Para cualquier porcentaje: (Cantidad × Porcentaje) ÷ 100.
Ejemplo: El 15% de 200 = (200 × 15) ÷ 100 = 3.000 ÷ 100 = 30.', 'Una camisa cuesta 40 dólares y tiene un descuento del 25%. ¿Cuánto dinero te descuentan y cuánto pagas al final?', 50, 1, 1, '2026-10-06 10:00:52');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (44, 1, 1, 6, 'miercoles', 6, 'Aludes Torrenciales y Flujos de Detritos en el Litoral', 'Aprende la física de los deslaves, la saturación del suelo y las obras de retención.', 'Alexander, en la geografía de La Guaira, las laderas montañosas del Waraira Repano son muy empinadas (pendientes de más de 45 grados).

¿QUÉ ES UN ALUD TORRENCIAL O FLUJO DE DETRITOS?
Cuando llueve de forma continua durante varios días sobre la montaña, la tierra actúa como una esponja. Llega un momento en que el suelo absorbe tanta agua que se SATURA POR COMPLETO.
Al saturarse, el peso del agua hace que la tierra pierda fricción y colapse ladera abajo. El agua ya no baja limpia: se convierte en un flujo denso y viscoso (como cemento fresco en movimiento) que arrastra rocas inmensas, árboles y sedimentos a gran velocidad por los cañones de los ríos.

OBRAS DE MITIGACIÓN EN LA GUAIRA:
Tras el evento de 1999, ingenieros venezolanos e internacionales construyeron en nuestras cuencas (como en Camurí Grande, Osorio, Curucutí y San Julián) PRENDAS Y DIQUES DE RETENCIÓN DE SEDIMENTOS:
• Son muros de concreto perforados ubicados en la parte media de la montaña que atrapan las rocas gigantescas y los troncos, permitiendo que el agua fluya con menos fuerza destructiva hacia el mar.

MEDIDAS CLAVE DE SEGURIDAD:
• Nunca construir viviendas al borde de cauces o conos de deyección.
• Mantener los diques libres de maleza y escombros.
• Evacuar hacia cotas altas seguras cuando se emitan alertas meteorológicas de saturación de suelos.', 'Investiga qué función cumplen las presas de gaviones y diques abiertos construidos en los ríos de La Guaira.', 60, 2, 1, '2026-10-06 10:00:52');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (45, 1, 1, 6, 'jueves', 3, 'Resolución de Ecuaciones Lineales de Primer Grado', 'Domina el despeje de ecuaciones con coeficientes: 2x + b = c.', 'Una ecuación lineal es una balanza perfecta. El objetivo supremo es dejar a la incógnita ''x'' completamente aislada en uno de los lados.

PASOS DE ORO PARA RESOLVER: 2x + 6 = 20

1. Primero movemos los números que están sumando o restando:
   El +6 pasa al otro lado restando:
   2x = 20 - 6
   2x = 14

2. Segundo movemos el número que acompaña a la ''x'' multiplicando:
   El 2 que está multiplicando a la x pasa al otro lado a DIVIDIR:
   $x = 14 ÷ 2
   $x = 7

3. Verificación (¡el toque del matemático experto!):
   Reemplazamos x por 7 en la ecuación original:
   2 × (7) + 6 = 14 + 6 = 20.
   ¡20 es igual a 20! Ecuación resuelta con precisión total.', 'Resuelve en tu libreta: 3x + 5 = 26. ¿Cuánto vale x?', 50, 1, 1, '2026-10-06 10:00:52');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (46, 1, 1, 6, 'jueves', 4, 'La Batalla de Carabobo (1821) y el Genio de Bolívar', 'Estrategia militar, el papel de la caballería de Páez y el sello definitivo de la soberanía.', 'El 24 de junio de 1821, en la sabana de Carabobo, se libró la batalla cumbre que selló la independencia política de Venezuela frente al imperio español.

El Ejército Patriota, comandado por el Libertador Simón Bolívar, diseñó una maniobra táctica magistral. En lugar de atacar frontalmente las posiciones atrincheradas del general realista Miguel de la Torre, Bolívar ordenó al general José Antonio Páez y a su Primera División (los legendarios ''Bravos de Apure'' y la Legión Británica) realizar un movimiento envolvente por el flanco derecho a través de una estrecha pica.

A pesar del fuego concentrado, la Legión Británica resistió rodilla en tierra y la impetuosa caballería llanera de Páez flanqueó a los realistas, rompiendo sus líneas defensivas.

En menos de dos horas de combate heroico, el ejército libertador obtuvo una victoria contundente. Carabobo no solo liberó a Caracas y al centro de Venezuela, sino que consolidó la base territorial para que Bolívar marchara a liberar el sur (Ecuador, Perú y Bolivia).', 'Menciona a tres héroes que combatieron en la Batalla de Carabobo.', 50, 2, 1, '2026-10-06 10:00:52');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (47, 1, 1, 6, 'viernes', 6, 'Sismos Marinos y Alertas de Tsunami en el Litoral Central', 'Aprende qué es un tsunami, por qué la retirada del mar es la alarma vital y cómo evacuar.', 'Alexander, al vivir en la franja costera de La Guaira frente al Mar Caribe, es fundamental comprender qué es un TSUNAMI (ola de puerto o maremoto).

¿CÓMO SE ORIGINA UN TSUNAMI?
Cuando ocurre un terremoto de gran magnitud (habitualmente superior a 7,0 grados) con epicentro bajo el fondo del mar o cerca de la costa, el lecho marino se deforma o desplaza verticalmente de golpe. Esto empuja toda la columna de agua oceánica hacia arriba, generando una serie de ondas que viajan a cientos de kilómetros por hora.

Al acercarse a aguas poco profundas cerca de la playa, la ola pierde velocidad pero CRECE ENORMEMENTE EN ALTURA y penetra en tierra firme con una fuerza hidráulica colosal.

LA SEÑAL NATURAL MÁS CRÍTICA:
Si ocurre un sismo muy fuerte en La Guaira (que dificulte mantenerse de pie) y minutos después observas que EL MAR SE RETIRA DE FORMA ANORMAL hacia adentro dejando el fondo marino descubierto con peces saltando:
¡ESA ES LA ALARMA INMEDIATA DE LA NATURALEZA!

REGLA DE EVACUACIÓN EN LA GUAIRA:
• NO esperar sirenas, mensajes de texto ni publicaciones en redes.
• NO acercarse a la orilla a mirar los peces.
• EVACUAR A PIE DE INMEDIATO hacia COTAS ALTAS (subir a zonas que estén a más de 20 o 30 metros sobre el nivel del mar, hacia las laderas seguras de la montaña).
• Permanecer en la zona alta hasta que las autoridades de Protección Civil confirmen que el tren de olas ha cesado (un tsunami no es una sola ola, son varias olas separadas por minutos).', 'Identifica en tu comunidad cuál es la ruta más rápida para subir a un terreno alto y seguro lejos de la orilla de la playa.', 70, 1, 1, '2026-10-06 10:00:52');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (48, 1, 1, 6, 'viernes', 2, 'Regla de Tres Simple Directa: Proporciones en la Práctica', 'Aprende a calcular proporciones para recetas, distancias y precios.', 'La regla de tres simple es una de las fórmulas más útiles para resolver situaciones de la vida real cuando tres datos son conocidos y queremos averiguar el cuarto.

REGLA DIRECTA:
Si 4 paquetes de galletas cuestan 6 dólares, ¿cuánto costarán 10 paquetes de las mismas galletas?

Planteamiento:
   4 paquetes  ───>  6 dólares
  10 paquetes  ───>  $x dólares

Método cruzado:
Multiplicamos en diagonal los dos datos conocidos y dividimos entre el que queda en diagonal con la $x:
  $x = (10 × 6) ÷ 4
  $x = 60 ÷ 4 = 15 dólares.

¡Fácil, rápido y exacto!', 'Si un automóvil recorre 150 km en 2 horas a velocidad constante, ¿cuántos kilómetros recorrerá en 5 horas?', 50, 2, 1, '2026-10-06 10:00:52');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (52, 1, 1, 6, 'miercoles', 13, 'Los Cinco Reinos de la Vida y la Megabiodiversidad de Venezuela', 'Clasificación taxonómica de los seres vivos y por qué nuestro país es un tesoro natural del planeta.', 'La Biología organiza la inmensa diversidad de la vida en cinco grandes reinos taxonómicos, propuestos clásicamente por Robert Whittaker:

1. Reino Mónera: Bacterias unicelulares y microscópicas sin núcleo definido (células procariotas).
2. Reino Protista: Organismos unicelulares más complejos como las amebas, paramecios y protozoarios (eucariotas).
3. Reino Fungi (Hongos): Organismos heterótrofos descomponedores como las setas, levaduras y mohos. (Nota clave: no hacen fotosíntesis, no son plantas).
4. Reino Plantae: Organismos pluricelulares autótrofos que realizan la fotosíntesis.
5. Reino Animalia: Organismos pluricelulares heterótrofos con tejidos especializados y capacidad de desplazamiento.

VENEZUELA: UN PAÍS MEGADIVERSO
Venezuela ocupa el puesto número 10 entre los países con mayor biodiversidad biológica de todo el planeta Tierra. Posee más de 1.400 especies de aves (casi el 15% de las aves del mundo) y ecosistemas tan variados como arrecifes de coral en el Caribe, bosques nublados en la Cordillera de la Costa y selvas amazónicas milenarias.', 'Elabora un cuadro mental comparando el Reino Fungi y el Reino Plantae. ¿Por qué los champiñones no son plantas?', 50, 3, 1, '2026-10-06 13:19:10');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (53, 1, 1, 6, 'jueves', 14, 'Derechos Humanos, Deberes y Convivencia Democrática', 'Comprende el equilibrio fundamental entre los derechos fundamentales y nuestras responsabilidades ciudadanas.', 'En 6to grado, nos preparamos para comprender cómo funciona la sociedad y el papel que desempeñamos como ciudadanos.

1. EL PRINCIPIO DE LA DIGNIDAD HUMANA
Todos los seres humanos nacen libres e iguales en dignidad y derechos. La Declaración Universal de los Derechos Humanos (1948) consagra derechos inalienables como la vida, la educación, la libertad de pensamiento y la protección de la infancia (LOPNNA en Venezuela).

2. LA OTRA CARA DE LA MONEDA: LOS DEBERES CIUDADANOS
Un derecho siempre viene acompañado de un deber correspondiente. No puede existir una sociedad sana donde todos exijan derechos pero nadie cumpla sus obligaciones:
• Si tengo derecho a estudiar en un colegio limpio ➔ Tengo el deber de cuidar los pupitres y botar la basura en su lugar.
• Si tengo derecho a expresar mi opinión ➔ Tengo el deber de escuchar y respetar las opiniones de los demás sin ofender.
• Si tengo derecho a vivir en una comunidad segura ➔ Tengo el deber de respetar las normas cívicas y colaborar con mis vecinos.

La democracia no es solo votar: es vivir con honestidad, justicia, solidaridad y responsabilidad en nuestro día a día.', 'Identifica tres derechos que disfrutes diariamente en tu vida y escribe al lado el deber correspondiente para cada uno.', 50, 3, 1, '2026-10-06 13:19:10');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (54, 1, 1, 6, 'viernes', 13, 'El Sistema Inmunológico: El Ejército Microscópico del Cuerpo', 'Explora cómo los glóbulos blancos, anticuerpos y vacunas defienden nuestra salud las 24 horas del día.', 'En cada segundo del día, nuestro cuerpo está en contacto con millones de microorganismos (bacterias, virus y hongos). Sin embargo, casi nunca nos enfermamos gracias a uno de los sistemas biológicos más sofisticados: el SISTEMA INMUNOLÓGICO.

LÍNEAS DE DEFENSA DEL ORGANISMO:
1. Barreras Físicas y Químicas: La piel, el sudor, las lágrimas y las mucosas impiden físicamente la entrada de gérmenes.
2. La Respuesta Innata (Glóbulos Blancos / Fagocitos): Si un microbio entra por una herida, los macrófagos y neutrófilos viajan por la sangre y ''se comen'' literalmente a los invasores.
3. La Respuesta Adaptativa (Linfocitos B y T): Producen ANTICUERPOS, que son proteínas especializadas en forma de ''Y'' diseñadas con precisión milimétrica para neutralizar un patógeno específico.

EL MILAGRO CIENTÍFICO DE LAS VACUNAS:
Las vacunas le enseñan al sistema inmune la ''foto'' de un virus debilitado o inofensivo. Los linfocitos generan células de memoria inmunológica. Así, si el virus real intenta entrar en el futuro, el cuerpo lo elimina inmediatamente antes de que cause daño.', 'Explica a un familiar con una analogía creativa (por ejemplo, un castillo medieval o un equipo de fútbol) cómo se defiende el sistema inmunológico.', 50, 3, 1, '2026-10-06 13:19:10');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (214, 1, 1, 6, 'lunes', 1, 'El Texto Expositivo: Estructura, Características y Síntesis de Información', 'Aprende a analizar textos objetivos, identificar la tesis y elaborar resúmenes precisos.', 'Un texto expositivo transmite información objetiva sin juicios personales del autor...', 'Lee un artículo científico corto y extrae 3 ideas clave en tu cuaderno.', 60, 1, 1, '2026-10-06 19:41:45');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (215, 1, 1, 6, 'martes', 3, 'Potenciación y Propiedades: Base, Exponente y Potencias de Base 10', 'Domina el cálculo de potencias, producto y cociente de potencias de igual base.', 'En an, a es la base y n el exponente. 2³ = 2 x 2 x 2 = 8. Al multiplicar potencias de igual base sumamos exponentes...', 'Calcula: 2⁴, 5³ y 10⁵ en tu cuaderno.', 60, 1, 1, '2026-10-06 19:41:45');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (216, 1, 1, 6, 'miercoles', 13, 'La Teoría Celular y los Niveles de Organización Biológica', 'Descubre cómo las células forman tejidos, órganos, sistemas e individuos completos.', 'Célula -> Tejido -> Órgano -> Sistema -> Organismo. Todos los seres vivos provienen de células preexistentes...', 'Dibuja la pirámide de los 5 niveles de organización biológica con un ejemplo humano.', 60, 1, 1, '2026-10-06 19:41:45');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (217, 1, 1, 6, 'jueves', 6, 'Geografía Política y Fronteras de Venezuela: Soberanía y Límites', 'Conoce los límites terrestres con Colombia, Brasil y Guyana, y la fachada caribeña.', 'Venezuela posee más de 2.800 km de costa y una estratégica posición geográfica en el norte de Sudamérica...', 'Identifica en el mapa los países limítrofes con Venezuela.', 60, 1, 1, '2026-10-06 19:41:45');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (218, 1, 1, 6, 'viernes', 14, 'Liderazgo Ético y Toma de Decisiones en la Pre-Adolescencia', 'Aprende a evaluar las consecuencias de tus actos antes de tomar decisiones importantes.', 'Un líder ético guía con el ejemplo, defiende a los débiles y actúa con rectitud...', 'Escribe una situación escolar donde tomar la decisión correcta requirió valentía.', 60, 1, 1, '2026-10-06 19:41:45');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (57, 2, 1, 5, 'lunes', 1, 'El Mito de Amalivaca y la Creación del Orinoco', 'Leyenda indígena sobre cómo se formaron las aguas y piedras del gran río.', 'Según la tradición de los pueblos Tamanaco y Caribe del oriente y sur de Venezuela, en tiempos antiguos el mundo fue cubierto por una inmensa creciente de aguas.

El gran héroe mítico Amalivaca y su hermano Vochi llegaron remando en una canoa para ayudar a los seres vivos. Con sabiduría, Amalivaca esculpió los petroglifos en las rocas a orillas del río Orinoco para dejar mensajes eternos sobre la convivencia entre la humanidad, los animales y la selva.

Este mito nos enseña el inmenso respeto que nuestros antepasados tenían por las fuentes de agua dulce y cómo protegían la naturaleza.', 'Dibuja en tu cuaderno una de las rocas del río Orinoco con un símbolo indígena que represente el agua o el sol.', 50, 1, 1, '2026-10-06 15:18:44');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (58, 2, 1, 5, 'lunes', 2, 'Fracciones Deliciosas en la Cocina', 'Aprende a dividir alimentos en mitades, cuartos y octavos para resolver problemas reales.', 'Una fracción representa una parte de un todo que ha sido dividido en partes exactamente iguales.

Por ejemplo, si horneamos una rica torta casera y la cortamos en 4 porciones iguales, cada pedazo es 1/4 (un cuarto) de la torta. Si nos comemos 2 pedazos, nos hemos comido 2/4, lo cual es exactamente igual a 1/2 (la mitad).

El número de arriba se llama NUMERADOR (las partes que tomamos) y el de abajo se llama DENOMINADOR (en cuántas partes dividimos el total).', 'Imagina una pizza dividida en 8 pedazos. Si tú comes 3 pedazos y tu hermano come 2, ¿cuántos pedazos quedan?', 50, 2, 1, '2026-10-06 15:18:44');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (59, 2, 1, 5, 'martes', 3, 'Descifrando Secuencias y Patrones con Kiko', 'Encuentra las reglas ocultas que siguen las series de números y figuras.', 'Un patrón numérico es una lista de números que sigue una regla fija y predecible.

Por ejemplo, observa la serie: 3, 6, 9, 12, ... ¿Qué número sigue? La regla es sumar 3 en cada paso (+3), por lo que el siguiente número es 15.

Los detectives matemáticos como Kiko el Periquito encuentran estas reglas comparando la distancia entre números vecinos. ¡El álgebra empieza aprendiendo a ver estas regularidades!', 'Descifra la siguiente serie y di la regla: 5, 10, 20, 40, ... ¿Qué número viene después?', 50, 1, 1, '2026-10-06 15:18:44');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (60, 2, 1, 5, 'martes', 13, 'El Árbol Nacional: El Araguaney y la Floración Dorada', 'Conoce cómo el Araguaney sobrevive a la sequía y viste a Venezuela de amarillo resplandeciente.', 'El Araguaney (Handroanthus chrysanthus) fue declarado Árbol Nacional de Venezuela el 29 de mayo de 1948.

Su nombre proviene de un vocablo indígena caribe: ''aravenei''. Este árbol tiene una adaptación biológica asombrosa: durante los meses de sequía (entre febrero y abril), pierde todas sus hojas verdes para no perder agua por evaporación, y de repente estalla en una floración amarilla dorada completa que dura pocos días, atrayendo a miles de abejas y aves polinizadoras.

Es un símbolo de resistencia, renacimiento y belleza de nuestra flora.', 'Comenta con tu papá qué otros árboles venezolanos florecen con colores vivos durante el verano.', 50, 2, 1, '2026-10-06 15:18:44');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (69, 2, 1, 5, 'lunes', 1, 'El Párrafo: Oración Principal y Conectores de Causa y Efecto', 'Aprende a estructurar párrafos usando conectores como porque, por tanto y debido a.', 'Un párrafo es un conjunto de oraciones que desarrollan una misma idea...', 'Redacta un párrafo de 5 líneas sobre tu comida favorita usando al menos dos conectores.', 50, 1, 1, '2026-10-06 19:41:42');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (70, 2, 1, 5, 'martes', 2, 'Adición y Sustracción con Números Decimales', 'Domina la alineación correcta de la coma decimal para sumar y restar con precisión.', 'Para sumar o restar números decimales, alineamos siempre las comas en una misma columna...', 'Resuelve: 456,78 + 89,45 y 500 - 123,45 en tu cuaderno.', 50, 1, 1, '2026-10-06 19:41:42');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (71, 2, 1, 5, 'miercoles', 13, 'La Fotosíntesis: La Gran Fábrica Verde de Oxígeno', 'Descubre cómo las plantas convierten la luz solar, agua y CO2 en glucosa y oxígeno.', 'Las plantas son organismos autótrofos capaces de producir su propio alimento gracias a la fotosíntesis...', 'Explica por qué los bosques son llamados los pulmones del planeta.', 50, 1, 1, '2026-10-06 19:41:42');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (72, 2, 1, 5, 'jueves', 6, 'Estados y Regiones de Venezuela: Los Andes y el Litoral', 'Conoce las diferentes regiones geográficas y climas de nuestro país.', 'Venezuela está dividida en grandes regiones naturales: Los Andes, Los Llanos, Guayana y Costa-Montaña...', 'Menciona tres estados que pertenecen a la región Costa-Montaña.', 50, 1, 1, '2026-10-06 19:41:42');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (73, 2, 1, 5, 'viernes', 14, 'Derechos y Deberes de los Niños: LOPNNA y Protección', 'Aprende que todo derecho implica un deber correspondiente para crecer en equilibrio.', 'La LOPNNA protege los derechos de niños y adolescentes en Venezuela...', 'Escribe dos deberes que tienes en tu hogar para apoyar a tu familia.', 50, 1, 1, '2026-10-06 19:41:42');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (61, 2, 1, 6, 'lunes', 1, 'Textos Argumentativos: El Poder de Justificar con Razones', 'Aprende a defender tu punto de vista con argumentos sólidos y respetuosos.', 'Un texto argumentativo tiene como objetivo convencer al lector sobre una idea o postura respecto a un tema importante.

Se compone de tres partes esenciales:
1. TESIS: La opinión o postura principal que se defiende.
2. ARGUMENTOS: Las razones, datos y evidencias que demuestran por qué la tesis es válida.
3. CONCLUSIÓN: El cierre reflexivo que reafirma la idea principal.

Saber argumentar nos permite dialogar con respeto, defender nuestros derechos y participar como ciudadanos conscientes.', 'Escribe una frase argumentativa con la estructura: Yo opino que [X] porque [Razón 1] y [Razón 2].', 50, 1, 1, '2026-10-06 15:18:44');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (62, 2, 1, 6, 'lunes', 2, 'Ecuaciones de Primer Grado: El Despeje de la Incógnita', 'Domina el arte de aislar la "x" en una igualdad matemática usando operaciones inversas.', 'Una ecuación es una balanza en perfecto equilibrio. Lo que hagamos en el lado izquierdo debemos hacerlo exactamente en el derecho para no romper la igualdad.

Para despejar una incógnita (como ''x''):
- Si un número está SUMANDO, pasa al otro lado RESTANDO (x + 5 = 12 ➔ x = 12 - 5 ➔ x = 7).
- Si un número está MULTIPLICANDO, pasa al otro lado DIVIDIENDO (3x = 18 ➔ x = 18 / 3 ➔ x = 6).

Con esta regla simple de operaciones inversas, cualquier misterio algebraico puede ser resuelto paso a paso.', 'Resuelve en papel: Si 2x + 4 = 16, ¿cuánto vale x?', 50, 2, 1, '2026-10-06 15:18:44');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (63, 2, 1, 6, 'martes', 13, 'Cadenas Tróficas y Niveles de Energía en el Ecosistema', 'Cómo fluye la energía del Sol a través de productores, consumidores y descomponedores.', 'En cualquier ecosistema de nuestro planeta, los seres vivos están conectados por relaciones alimentarias denominadas redes o cadenas tróficas.

1. PRODUCTORES: Plantas y algas que producen su propio alimento mediante la fotosíntesis usando la luz solar.
2. CONSUMIDORES PRIMARIOS (Herbívoros): Animales como el chigüire que se alimentan de plantas.
3. CONSUMIDORES SECUNDARIOS (Carnívoros): Depredadores como el jaguar o la nutria gigante.
4. DESCOMPONEDORES: Hongos y bacterias que reciclan la materia orgánica devolviendo minerales al suelo.

Si un eslabón de la cadena se rompe por la contaminación o caza excesiva, todo el ecosistema sufre un desequilibrio.', 'Traza una cadena trófica venezolana de 3 niveles: planta ➔ herbívoro ➔ carnívoro.', 50, 1, 1, '2026-10-06 15:18:44');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (219, 2, 1, 6, 'lunes', 1, 'Cohesión y Coherencia: Conectores de Oposición y Consecuencia', 'Aprende a hilar argumentos con conectores como sin embargo, no obstante, por consiguiente.', 'La coherencia da sentido global al texto; la cohesión une las oraciones mediante conectores lógicos...', 'Reescribe dos oraciones independientes uniéndolas con "por lo tanto" o "sin embargo".', 60, 1, 1, '2026-10-06 19:41:45');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (220, 2, 1, 6, 'martes', 3, 'Radicación Exacta e Introducción a las Raíces Cuadradas', 'Descubre la operación inversa a la potenciación para hallar la base original.', 'La raíz cuadrada de un número x es el número que multiplicado por sí mismo da x. √25 = 5 porque 5² = 25...', 'Calcula: √36, √64, √100 y √144 en tu cuaderno.', 60, 1, 1, '2026-10-06 19:41:45');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (221, 2, 1, 6, 'miercoles', 13, 'Genética Básica: ADN, Cromosomas y Herencia de Caracteres', 'Descubre cómo heredamos el color de ojos, cabello y rasgos de padres y abuelos.', 'El ADN contiene el código genético empaquetado en 23 pares de cromosomas en las células humanas...', 'Haz una lista de 3 rasgos físicos que heredaste de tu mamá y 3 de tu papá.', 60, 1, 1, '2026-10-06 19:41:45');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (222, 2, 1, 6, 'jueves', 6, 'Límites Marítimos y Fachada Caribeña de Venezuela: Zona Económica', 'Conoce la importancia de Isla de Aves y nuestro territorio marítimo insular.', 'Isla de Aves otorga a Venezuela una extensa Zona Económica Exclusiva en el mar Caribe...', 'Investiga qué distancia aproximada tiene Isla de Aves respecto a tierra firme venezolana.', 60, 1, 1, '2026-10-06 19:41:45');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (223, 2, 1, 6, 'viernes', 14, 'Madurez Emocional: Manejo de la Frustración y la Ira', 'Aprende técnicas para canalizar emociones intensas con inteligencia y asertividad.', 'Sentir enojo es normal, pero reaccionar con agresión es una elección destructiva...', 'Escribe tres pasos que puedes aplicar cuando sientas que pierdes la paciencia.', 60, 1, 1, '2026-10-06 19:41:45');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (74, 3, 1, 5, 'lunes', 1, 'Sinónimos, Antónimos y Enriquecimiento de Vocabulario', 'Descubre cómo ampliar tu vocabulario para expresarte con mayor elegancia y exactitud.', 'Los sinónimos son palabras que tienen un significado similar, mientras que los antónimos significan lo opuesto...', 'Escribe tres parejas de sinónimos y tres de antónimos en tu cuaderno.', 50, 1, 1, '2026-10-06 19:41:42');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (75, 3, 1, 5, 'martes', 2, 'Multiplicación por Dos y Tres Cifras', 'Multiplica con soltura y comprende el algoritmo y la propiedad conmutativa y asociativa.', 'Para multiplicar números de varias cifras, multiplicamos primero las unidades, luego las decenas dejando el espacio...', 'Calcula: 245 x 36 en tu cuaderno.', 50, 1, 1, '2026-10-06 19:41:42');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (76, 3, 1, 5, 'miercoles', 13, 'Ecosistemas Terrestres y Acuáticos de Venezuela', 'Explora la gran diversidad de flora y fauna en sabanas, selvas y arrecifes de coral.', 'Un ecosistema es una comunidad de seres vivos que interactúan con su medio físico...', 'Describe brevemente las características de un ecosistema de manglar en Venezuela.', 50, 1, 1, '2026-10-06 19:41:42');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (77, 3, 1, 5, 'jueves', 6, 'El Relieve Venezolano: Picos Nevados y Grandes Llanuras', 'Aprende a diferenciar valles, mesetas (tepuyes) y llanuras en el mapa físico.', 'Venezuela posee tepuyes milenarios en Guayana y picos nevados en Mérida...', 'Dibuja en tu cuaderno el perfil de un tepuy y explica qué lo hace único.', 50, 1, 1, '2026-10-06 19:41:42');
INSERT INTO "activities" ("id", "week_number", "lapso", "grade", "day_of_week", "subject_id", "title", "summary", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_active", "created_at") VALUES (78, 3, 1, 5, 'viernes', 14, 'Hábitos de Estudio y Gestión del Tiempo Diario', 'Organiza tu rutina de tareas para aprender sin estrés y disfrutar de tu tiempo libre.', 'El éxito escolar no depende de estudiar a última hora, sino de la constancia...', 'Elabora un horario semanal de 30 minutos diarios dedicado al estudio de misiones.', 50, 1, 1, '2026-10-06 19:41:42');
