INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (111, 25, '¿Cuál es el nombre del Salto Ángel en lengua indígena según la tradición Pemón?', 'multiple_choice', '["Orinoco Dorado","Auyantepuy Mayor","Waraira Repano","Kerepakupai Vená"]', 'Kerepakupai Vená', 'Excelente. Los pemones llaman a la catarata Kerepakupai Vená o Churún Merú.', 10);
INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (112, 25, '¿En qué estado de Venezuela se encuentra ubicado el Auyantepuy?', 'multiple_choice', '["Estado La Guaira","Estado Zulia","Estado Amazonas","Estado Bolívar"]', 'Estado Bolívar', '¡Correcto! El Parque Nacional Canaima y el Auyantepuy están en el estado Bolívar.', 10);
INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (113, 25, '¿Aproximadamente cuántos metros de caída ininterrumpida de agua tiene el Salto Ángel?', 'multiple_choice', '["500 metros","979 metros","250 metros","1.500 metros"]', '979 metros', '¡Exacto! Son 979 metros, lo que la convierte en la catarata más alta del mundo.', 10);
INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (114, 25, '¿Qué ríos reciben las aguas que caen desde la cumbre del Auyantepuy?', 'multiple_choice', '["El río Guaire y el Manzanares","El lago de Valencia","Los ríos Churún y Caroní","El río Osorio y Camurí"]', 'Los ríos Churún y Caroní', '¡Muy bien! Las aguas alimentan al río Churún y posteriormente desembocan en el Caroní.', 10);
INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (115, 25, 'Los antiguos pueblos pemones consideraban a los tepuyes como montañas sagradas y guardianes del tiempo.', 'true_false', '["Verdadero","Falso"]', 'Verdadero', '¡Verdadero! Para ellos, estas mesetas milenarias son moradas espirituales sagradas.', 10);
INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (116, 25, '¿Qué significa la palabra "ininterrumpida" cuando el texto describe la caída de agua?', 'multiple_choice', '["Que cae directa y continuamente sin chocar ni detenerse en el camino","Que el agua sale caliente","Que cae únicamente en las noches","Que el río está seco"]', 'Que cae directa y continuamente sin chocar ni detenerse en el camino', '¡Brillante vocabulario! Significa que el chorro desciende en caída libre sin interrupciones.', 10);
INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (117, 25, 'Escribe con tus propias palabras qué lección nos deja el pueblo Pemón sobre el respeto y cuidado de la naturaleza.', 'reflexive', NULL, '', 'Tu papá leerá tu reflexión con mucha atención para valorarla.', 15);
INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (118, 26, 'Nivel 1 (Básico): ¿Cuál es la regla de oro para sumar y restar números decimales en papel?', 'multiple_choice', '["Quitar todas las comas y no volverlas a poner","Multiplicar los números primero","Sumar siempre de izquierda a derecha sin importar la coma","Colocar la coma debajo de la coma alineando unidades con unidades"]', 'Colocar la coma debajo de la coma alineando unidades con unidades', '¡Exacto! Alinear la coma asegura sumar décimas con décimas y unidades con unidades.', 10);
INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (119, 26, 'Nivel 2 (Cálculo Directo): ¿Cuál es el resultado exacto de sumar 14,30 + 5,25?', 'multiple_choice', '["18,50","19,55","19,05","20,55"]', '19,55', '¡Muy bien! 14 + 5 = 19 y 0,30 + 0,25 = 0,55, sumando 19,55.', 10);
INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (120, 26, 'Nivel 3 (Situación Cotidiana): En el mercado compras un kilo de queso por 6,50 $ y un cartón de huevos por 4,30 $. ¿Cuánto gastas en total?', 'multiple_choice', '["9,80 $","10,50 $","11,00 $","10,80 $"]', '10,80 $', '¡Correcto! 6,50 + 4,30 = 10,80 $.', 10);
INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (121, 26, 'Nivel 4 (Resta de Cambio): Si pagas con un billete de 20,00 $ una cuenta que costó exactamente 12,40 $, ¿cuánto dinero te deben dar de vuelto?', 'multiple_choice', '["7,60 $","8,00 $","7,40 $","8,60 $"]', '7,60 $', '¡Excelente resta! 20,00 - 12,40 = 7,60 $.', 10);
INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (122, 26, 'Nivel 5 (Desafío Maestro): Dimas tiene 15,00 $. Compra 2 cuadernos de 3,50 $ cada uno (total 7,00 $) y un paquete de galletas de 2,25 $. ¿Cuánto gastó en total y cuánto le sobró?', 'multiple_choice', '["Gastó 9,25 $ y le sobraron 5,75 $","Gastó 8,50 $ y le sobraron 6,50 $","Gastó 9,75 $ y le sobraron 5,25 $","Gastó 10,00 $ y le sobraron 5,00 $"]', 'Gastó 9,25 $ y le sobraron 5,75 $', '¡Magistral! Gastó 7,00 + 2,25 = 9,25 $. Le sobraron 15,00 - 9,25 = 5,75 $.', 15);
INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (123, 27, '¿Cuáles son los dos gigantes naturales entre los que se encuentra ubicada la franja de La Guaira?', 'multiple_choice', '["El Río Orinoco y la Gran Sabana","Los Andes y el Lago de Maracaibo","El Mar Caribe y el Parque Nacional Waraira Repano","El Desierto y los Llanos"]', 'El Mar Caribe y el Parque Nacional Waraira Repano', '¡Correcto! Vivimos en una estrecha franja costera entre el mar y montañas muy empinadas.', 10);
INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (124, 27, '¿Por qué nunca debemos arrojar basura ni escombros en los cauces de las quebradas de La Guaira?', 'multiple_choice', '["No tiene ninguna importancia","Solo porque se ve sucio","Porque la basura bloquea los diques y puentes, provocando desbordamientos","Porque los peces se confunden"]', 'Porque la basura bloquea los diques y puentes, provocando desbordamientos', '¡Crucial! Mantener las quebradas limpias permite que el agua fluya libremente y salva vidas.', 10);
INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (125, 27, 'Las montañas de La Guaira son muy empinadas, lo que hace que el agua de lluvia baje con gran velocidad hacia el mar.', 'true_false', '["Verdadero","Falso"]', 'Verdadero', '¡Verdadero! Por eso los ríos y quebradas de nuestro litoral tienen corrientes veloces.', 10);
INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (126, 27, '¿Cuál es la primera acción de seguridad que debe hacer un niño si observa que una quebrada empieza a crecer con fuerza?', 'multiple_choice', '["Alejarse de la orilla de inmediato, avisar a los adultos y subir a una zona alta","Quedarse mirando a ver qué pasa","Intentar cruzar nadando","Bañarse en la orilla"]', 'Alejarse de la orilla de inmediato, avisar a los adultos y subir a una zona alta', '¡Exacto! La prioridad número uno es ponerse a salvo en una cota alta y segura.', 10);
INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (127, 27, 'Escribe qué quebrada o río pasa más cerca de tu casa o comunidad y cómo podemos cuidarla entre todos.', 'reflexive', NULL, '', 'Tu papá evaluará tu respuesta y conocimiento de la comunidad.', 10);
INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (128, 28, 'Nivel 1 (Básico): En una balanza en equilibrio, si en un plato hay (Caja Secreta + 3 kg) y en el otro plato hay 10 kg, ¿cuánto pesa la caja?', 'multiple_choice', '["7 kg","3 kg","13 kg","10 kg"]', '7 kg', '¡Muy bien! 10 - 3 = 7 kg. El número escondido es 7.', 10);
INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (129, 28, 'Nivel 2 (Deducción Directa): Si 2 piñas exactamente iguales pesan lo mismo que 8 kilos en total, ¿cuánto pesa una sola piña?', 'multiple_choice', '["4 kg","6 kg","16 kg","2 kg"]', '4 kg', '¡Excelente! 8 ÷ 2 = 4 kg cada piña.', 10);
INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (130, 28, 'Nivel 3 (Incógnita con Frutas): Una balanza equilibra 1 Sandía con (2 Melones de 3 kg cada uno + 1 pesa de 2 kg). ¿Cuánto pesa la Sandía?', 'multiple_choice', '["8 kg","6 kg","5 kg","10 kg"]', '8 kg', '¡Genial! 2 melones pesan (2 × 3 = 6 kg) + 2 kg de pesas = 8 kg.', 10);
INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (131, 28, 'Nivel 4 (Ecuación con Sustracción): Si a un número secreto le quitamos 6 y obtenemos 14, ¿cuál es el número secreto original?', 'multiple_choice', '["8","20","24","14"]', '20', '¡Brillante! Lo contrario de restar es sumar: 14 + 6 = 20.', 10);
INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (132, 28, 'Nivel 5 (Desafío Maestro): Si 1 pelota + 1 carrito pesan 15 kg en total, y el carrito pesa el doble que la pelota (carrito = 2 pelotas), ¿cuánto pesa la pelota?', 'multiple_choice', '["7 kg","3 kg","10 kg","5 kg"]', '5 kg', '¡Impresionante! Pelota (5 kg) + Carrito (10 kg) = 15 kg en total. ¡Pensamiento algebraico puro!', 15);
INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (133, 31, 'Nivel 1 (Básico): Al multiplicar un decimal por 10, 100 o 1.000, ¿hacia qué lado se corre la coma?', 'multiple_choice', '["No se mueve","Hacia la izquierda","Hacia la derecha","Hacia arriba"]', 'Hacia la derecha', '¡Correcto! Cada cero corre la coma un lugar a la derecha.', 10);
