INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (135, 31, 'Nivel 3 (Multiplicar por 100): Resuelve: 0,78 × 100 = ?', 'multiple_choice', '["0,780","78","780","7,8"]', '78', '¡Exacto! Se corre la coma 2 lugares: 78.', 10);
