INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (137, 31, 'Nivel 5 (Desafío Maestro en el Negocio): Un comerciante vende 100 bolsas de avena a 1,45 $ cada una. ¿Cuánto dinero recibe en total?', 'multiple_choice', '["14,50 $","145,50 $","145 $","1.450 $"]', '145 $', '¡Genial! 1,45 × 100 = 145 $ exactos.', 15);
