INSERT INTO "activity_questions" ("id", "activity_id", "question_text", "question_type", "options_json", "correct_answer", "explanation", "points") VALUES (259, 58, 'En la fracción 3/4, ¿qué número representa el Denominador?', 'multiple_choice', '["El número 7","El número 4","El número 1","El número 3"]', 'El número 4', 'El denominador es el número inferior que indica las partes totales en que se dividió el objeto.', 10);
