-- Datos para tabla: material_bank (40 registros)
INSERT INTO "material_bank" ("id", "grade", "lapso", "lapso_week", "absolute_week", "day_of_week", "subject_id", "title", "summary", "daily_objective", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_deployed", "created_at") VALUES (1, 5, 1, 1, 1, 'lunes', 1, 'El Viaje de la Semilla: Idea Principal y Secuencia Narrativa', 'Aprende a identificar la idea principal en un cuento y distinguir el inicio, nudo y desenlace.', 'Comprender la estructura de los textos narrativos e identificar la idea principal y los personajes.', 'Los textos narrativos cuentan historias reales o imaginarias que ocurren en un lugar y tiempo determinados. Toda narración bien construida tiene tres partes fundamentales:

1. **Inicio:** Se presentan los personajes, el lugar y la situación inicial.
2. **Nudo o conflicto:** Ocurre un problema o acontecimiento que cambia la tranquilidad de los personajes.
3. **Desenlace:** Se resuelve el conflicto y concluye la historia.

Para hallar la **idea principal**, pregúntate siempre: *¿De qué o de quién trata principalmente el texto y qué es lo más importante que se dice sobre ello?*', 'Escribe en tu cuaderno un cuento corto de 6 líneas sobre una mascota que encuentra un mapa secreto. Señala con colores distintos el inicio, el nudo y el desenlace.', 50, 1, 1, '2026-10-06 19:41:38');
INSERT INTO "material_bank" ("id", "grade", "lapso", "lapso_week", "absolute_week", "day_of_week", "subject_id", "title", "summary", "daily_objective", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_deployed", "created_at") VALUES (2, 5, 1, 1, 1, 'martes', 2, 'El Sistema de Numeración Decimal: Unidades, Decenas y Millones', 'Descubre cómo cada dígito cambia de valor según su posición en la tabla de valor posicional.', 'Comprender el sistema de numeración decimal y el valor de posición hasta los millones.', 'Nuestro sistema de numeración es **posicional y de base 10**. Esto significa que diez unidades de un orden forman una unidad del orden inmediatamente superior:

- 10 Unidades (U) = 1 Decena (D)
- 10 Decenas (D) = 1 Centena (C)
- 10 Centenas (C) = 1 Unidad de Mil (UM)
- 1.000 Unidades de Mil = 1 Unidad de Millón (UMi)

Por ejemplo, en el número **4.528.319**:
El dígito 4 está en las unidades de millón y vale 4.000.000.
El dígito 5 está en las centenas de mil y vale 500.000.', 'Descompón aditivamente el número 3.842.105 según el valor posicional de cada una de sus cifras en tu cuaderno.', 50, 1, 1, '2026-10-06 19:41:38');
INSERT INTO "material_bank" ("id", "grade", "lapso", "lapso_week", "absolute_week", "day_of_week", "subject_id", "title", "summary", "daily_objective", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_deployed", "created_at") VALUES (3, 5, 1, 1, 1, 'miercoles', 13, 'La Célula: El Ladrillo Fundamental de los Seres Vivos', 'Explora cómo están formados todos los organismos vivos y la diferencia entre células animales y vegetales.', 'Identificar la célula como unidad básica de todo ser vivo y diferenciar animales y vegetales.', 'Todos los seres vivos en la Tierra, desde las bacterias microscópicas hasta los jaguares y samanes, están formados por **células**. Las tres partes esenciales de toda célula eucariota son:

1. **Membrana plasmática:** Envoltura que protege a la célula y controla qué sustancias entran y salen.
2. **Citoplasma:** Líquido gelatinoso donde flotan los organelos encargados de las funciones celulares.
3. **Núcleo:** El centro de mando que contiene el ADN (material genético).

*Diferencia clave:* Las células vegetales tienen **pared celular rígida** y **cloroplastos** (para hacer fotosíntesis con la luz solar), organelos que no tienen las células animales.', 'Dibuja en tu cuaderno una célula vegetal y rotula sus tres partes principales más la pared celular.', 50, 1, 1, '2026-10-06 19:41:38');
INSERT INTO "material_bank" ("id", "grade", "lapso", "lapso_week", "absolute_week", "day_of_week", "subject_id", "title", "summary", "daily_objective", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_deployed", "created_at") VALUES (4, 5, 1, 1, 1, 'jueves', 6, 'Nuestra Geografía: La Cordillera de la Costa y La Guaira', 'Conoce cómo las montañas se unen con el mar Caribe en La Guaira y por qué debemos cuidar las cuencas.', 'Reconocer el relieve y la geografía del Litoral Central y las medidas básicas de prevención.', 'El estado La Guaira posee una geografía muy especial: es una estrecha franja costera flanqueada por la imponente **Cordillera de la Costa** (Parque Nacional Waraira Repano) y el mar Caribe.

Debido a que las montañas tienen pendientes muy pronunciadas, las quebradas y ríos bajan rápidamente hacia el mar. Cuando caen lluvias torrenciales continuas, el agua arrastra sedimentos y rocas.

Por esta razón, la **gestión de riesgos** es una prioridad para todos los guaireños:
- Mantener limpias las quebradas sin arrojar basura.
- Reforestar las laderas montañosas para que las raíces afiancen la tierra.
- Conocer las rutas de evacuación hacia zonas altas y seguras.', 'Conversa con tu familia e identifiquen juntos cuál es la zona alta más segura cercana a su vivienda en caso de lluvias fuertes.', 50, 1, 1, '2026-10-06 19:41:38');
INSERT INTO "material_bank" ("id", "grade", "lapso", "lapso_week", "absolute_week", "day_of_week", "subject_id", "title", "summary", "daily_objective", "reading_content", "practical_exercise", "xp_reward", "order_num", "is_deployed", "created_at") VALUES (5, 5, 1, 1, 1, 'viernes', 14, 'El Arte de Convivir: Acuerdos de Paz y Respeto Mutuo', 'Descubre por qué las normas no son castigos sino acuerdos que protegen nuestros derechos.', 'Valorar la convivencia escolar, el respeto mutuo y las normas como base de la paz.', 'La convivencia es la capacidad de vivir juntos en armonía, respetando las ideas, gustos y diferencias de los demás. En la casa y en la escuela, los **acuerdos de convivencia** son indispensables:

- **Escucha activa:** Escuchar cuando otra persona habla sin interrumpirla.
- **Palabras mágicas:** Por favor, gracias, con permiso y disculpa.
- **Empatía:** Ponerse en los zapatos del compañero antes de emitir un juicio.
- **Solución pacífica:** Dialogar con calma cuando surge un desacuerdo en lugar de pelear o gritar.

Cuando practicamos estos valores, nuestro hogar y nuestra aula se convierten en un refugio de aprendizaje y amistad.', 'Escribe en tu cuaderno tres acuerdos de convivencia que te comprometes a cumplir esta semana en tu hogar con tus padres y hermanos.', 50, 1, 1, '2026-10-06 19:41:38');
