-- =========================================================================
-- POLÍTICAS DE ACCESO PÚBLICO / ACCESO A LA APLICACIÓN
-- Permite que la API de Supabase y la aplicación PHP lean y escriban sin trabas
-- =========================================================================

ALTER TABLE "users" ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'users' AND policyname = 'allow_all_users') THEN
    CREATE POLICY allow_all_users ON "users" FOR ALL USING (true) WITH CHECK (true);
  END IF;
END $$;

